// Logo da Athié Wohnrath para o rodapé dos relatórios, com o fundo
// verde já assado na própria imagem (gerada a partir de
// public/logos/athie-wohnrath-rodape.png). Embutida direto no código,
// em vez de referenciada por URL ou por uma div com cor de fundo via CSS,
// por dois motivos: (1) o relatório em PDF abre numa janela separada
// (window.open + document.write) que não carrega com confiabilidade
// recursos externos; (2) o fundo verde precisa estar nos pixels da própria
// imagem, e não em CSS background-color, porque a opção "Imprimir
// gráficos de segundo plano" costuma vir desligada por padrão no
// navegador — nesse caso um background-color de CSS simplesmente some do
// PDF gerado, enquanto o conteúdo de uma <img> sempre imprime.
export const LOGO_ATHIE_WOHNRATH_BASE64 =
  'data:image/png;base64,'
